// ----- Node-Logik -----
const roh = $input.first().json.plz_liste;
const liste = Array.isArray(roh) ? roh : [];
const sauber = [];
for (const x of liste) {
  const s = String(x === null || x === undefined ? '' : x).trim();
  if (/^[0-9]{5}$/.test(s) && !sauber.includes(s)) sauber.push(s);
}
const l = sauber.slice(0, 3);
return [{ json: { liste: l, p1: l[0] || '00000x', p2: l[1] || '00000x', p3: l[2] || '00000x' } }];

// ----- Node-Logik -----
const angefragt = $('PLZ normalisieren').first().json.liste;
const info = {};
for (const p of angefragt) info[p] = { gefunden: false };
let fehler = false;
for (const i of $input.all()) {
  const j = i.json || {};
  if (j.error) { fehler = true; continue; }
  if (j.plz && info[j.plz]) info[j.plz] = { gefunden: true, ort: j.ort || '', bundesland: j.bundesland || '' };
}
return [{ json: { ok: !fehler, plz_info: fehler ? {} : info } }];
